-- Everlake world import, slice 19: six recipe acquisitions
-- 2026_11_10_15_world_everlake_import_slice19.sql: generated by tools/forever-data in wow-project-everlake from public WoW Forever data.
-- Sources (pins): eg-link 9fcae73cc74fea4f1c4f, questiedb c0ce0c97ee449295ff1a, wago 1.60.1.70862
-- Written against the fork world forever-tdb-2026-10-14 + core 029c5dd9 + world-data 24a3b39e.
-- Rates are estimates from Wowhead Forever and Icy Veins. Vendor observation from Efficient Games (https://efficient.games), CC BY 4.0.
-- Never edit this file once it is deployed (the updater would run it and every later custom file again):
-- a later fix is a new file. Running it again changes nothing: see docs/forever-import.md.

CREATE TABLE IF NOT EXISTS `everlake_import_rows` (
  `tbl` varchar(64) NOT NULL COMMENT 'world table of the row',
  `k1` bigint NOT NULL COMMENT 'the row''s key, in the table''s primary key order',
  `k2` bigint NOT NULL DEFAULT '0',
  `k3` bigint NOT NULL DEFAULT '0',
  `k4` bigint NOT NULL DEFAULT '0',
  `file` varchar(200) NOT NULL COMMENT 'the update file that added the row',
  `note` varchar(255) NOT NULL DEFAULT '' COMMENT 'the sources that gave it',
  PRIMARY KEY (`tbl`, `k1`, `k2`, `k3`, `k4`),
  KEY `file` (`file`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Rows the Everlake world import added (docs/forever-import.md)';

SET SESSION autocommit = 0;
-- Observed drops for five existing crafting spells
DROP TEMPORARY TABLE IF EXISTS `everlake_import_stage`;
CREATE TEMPORARY TABLE `everlake_import_stage` (`Entry` int unsigned NOT NULL, `ItemType` tinyint NOT NULL, `Item` int unsigned NOT NULL, `Chance` float NOT NULL, `QuestRequired` tinyint(1) NOT NULL, `LootMode` smallint unsigned NOT NULL, `GroupId` tinyint unsigned NOT NULL, `MinCount` tinyint unsigned NOT NULL, `MaxCount` tinyint unsigned NOT NULL, `Comment` varchar(255) NOT NULL, `note` varchar(255) NOT NULL, `missing` tinyint NOT NULL DEFAULT '0', PRIMARY KEY (`Entry`, `ItemType`, `Item`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO `everlake_import_stage` (`Entry`, `ItemType`, `Item`, `Chance`, `QuestRequired`, `LootMode`, `GroupId`, `MinCount`, `MaxCount`, `Comment`, `note`) VALUES
(4116, 0, 254000, 0.05, 0, 1, 0, 1, 1, 'Earthen Leggings', 'Wowhead Forever drop rate; QuestieTrace pair corroboration; Wago On Learn 1257425'),
(4101, 0, 251385, 0.05, 0, 1, 0, 1, 1, 'Hard Gold Cuirass', 'Wowhead Forever drop rate; QuestieTrace pair corroboration; Wago On Learn 1252282'),
(2894, 0, 251394, 0.01, 0, 1, 0, 1, 1, 'Shining Mithril Boots', 'Wowhead Forever drop rate; QuestieTrace pair corroboration; Wago On Learn 1252291'),
(3711, 0, 251337, 0.12, 0, 1, 0, 1, 1, 'Sterling Silver Gauntlet', 'Wowhead Forever drop rate; QuestieTrace pair corroboration; Wago On Learn 1252234'),
(4830, 0, 253978, 0.713, 0, 1, 0, 1, 1, 'Filigreed Silky Circlet', 'Icy Veins drop rate; Wowhead Forever pair corroboration; Wago On Learn 1257414'),
(6243, 0, 253978, 1.15, 0, 1, 0, 1, 1, 'Filigreed Silky Circlet', 'Icy Veins drop rate; Wowhead Forever pair corroboration; Wago On Learn 1257414');
UPDATE `everlake_import_stage` s SET s.`missing` = 1 WHERE NOT EXISTS (SELECT 1 FROM `creature_loot_template` t WHERE t.`Entry` = s.`Entry` AND t.`ItemType` = s.`ItemType` AND t.`Item` = s.`Item`) AND EXISTS (SELECT 1 FROM `creature_template_difficulty` d JOIN `creature` c ON c.`id` = d.`Entry`
 WHERE d.`Entry` = s.`Entry` AND d.`DifficultyID` = 0 AND d.`LootID` = s.`Entry`
 AND c.`map` = CASE s.`Entry` WHEN 4116 THEN 1 WHEN 4101 THEN 1 WHEN 2894 THEN 0 WHEN 3711 THEN 1 WHEN 4830 THEN 48 WHEN 6243 THEN 48 END)
AND NOT EXISTS (SELECT 1 FROM `creature_template_difficulty` d WHERE d.`LootID` = s.`Entry` AND d.`Entry` <> s.`Entry`)
AND NOT EXISTS (SELECT 1 FROM `creature_loot_template` l JOIN `reference_loot_template` ref ON ref.`Entry` = l.`Item`
 WHERE l.`Entry` = s.`Entry` AND l.`ItemType` = 1 AND ref.`ItemType` = 0 AND ref.`Item` = s.`Item`)
AND NOT EXISTS (SELECT 1 FROM `creature_loot_template` l JOIN `reference_loot_template` r ON r.`Entry` = l.`Item`
 JOIN `reference_loot_template` ref ON ref.`Entry` = r.`Item` WHERE l.`Entry` = s.`Entry` AND l.`ItemType` = 1
 AND r.`ItemType` = 1 AND ref.`ItemType` = 0 AND ref.`Item` = s.`Item`)
AND NOT EXISTS (SELECT 1 FROM `everlake_import_rows` r WHERE r.`tbl` = 'creature_loot_template'
 AND r.`k1` = s.`Entry` AND r.`k2` = s.`ItemType` AND r.`k3` = s.`Item`);
INSERT INTO `creature_loot_template` (`Entry`, `ItemType`, `Item`, `Chance`, `QuestRequired`, `LootMode`, `GroupId`, `MinCount`, `MaxCount`, `Comment`) SELECT `Entry`, `ItemType`, `Item`, `Chance`, `QuestRequired`, `LootMode`, `GroupId`, `MinCount`, `MaxCount`, `Comment` FROM `everlake_import_stage` WHERE `missing` = 1;
INSERT INTO `everlake_import_rows` (`tbl`, `k1`, `k2`, `k3`, `file`, `note`) SELECT 'creature_loot_template', s.`Entry`, s.`ItemType`, s.`Item`, '2026_11_10_15_world_everlake_import_slice19.sql', s.`note` FROM `everlake_import_stage` s WHERE s.`missing` = 1 ON DUPLICATE KEY UPDATE `file` = '2026_11_10_15_world_everlake_import_slice19.sql', `note` = s.`note`;
DROP TEMPORARY TABLE `everlake_import_stage`;

-- Enchant Boots - Speed formula from faction enchanters
DROP TEMPORARY TABLE IF EXISTS `everlake_import_stage`;
CREATE TEMPORARY TABLE `everlake_import_stage` (`entry` int unsigned NOT NULL, `slot` smallint NOT NULL, `item` int NOT NULL, `maxcount` int unsigned NOT NULL, `incrtime` int unsigned NOT NULL, `ExtendedCost` int unsigned NOT NULL, `type` tinyint unsigned NOT NULL, `PlayerConditionID` int unsigned NOT NULL, `IgnoreFiltering` tinyint unsigned NOT NULL, `VerifiedBuild` int NOT NULL, `note` varchar(255) NOT NULL, `missing` tinyint NOT NULL DEFAULT '0', PRIMARY KEY (`entry`, `item`, `ExtendedCost`, `type`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO `everlake_import_stage` (`entry`, `slot`, `item`, `maxcount`, `incrtime`, `ExtendedCost`, `type`, `PlayerConditionID`, `IgnoreFiltering`, `VerifiedBuild`, `note`) VALUES
(256732, 1, 289560, 0, 0, 11842, 1, 163433, 0, 0, 'Merchant''s Favor 180; Honored; Wago On Learn 1328948'),
(248199, 40, 289560, 0, 0, 11857, 1, 163433, 0, 0, 'Merchant''s Favor 180; Honored; Wago On Learn 1328948');
UPDATE `everlake_import_stage` s SET s.`missing` = 1 WHERE NOT EXISTS (SELECT 1 FROM `npc_vendor` t WHERE t.`entry` = s.`entry` AND t.`item` = s.`item` AND t.`ExtendedCost` = s.`ExtendedCost` AND t.`type` = s.`type`) AND EXISTS (SELECT 1 FROM `creature_template` t JOIN `creature` c ON c.`id` = t.`entry`
 WHERE t.`entry` = s.`entry` AND (COALESCE(c.`npcflag`, t.`npcflag`) & 128) = 128
 AND c.`map` = CASE s.`entry` WHEN 256732 THEN 0 WHEN 248199 THEN 1 END)
AND EXISTS (SELECT 1 FROM `npc_vendor` v WHERE v.`entry` = s.`entry` AND v.`item` = 249537
 AND v.`ExtendedCost` = s.`ExtendedCost` AND v.`type` = 1)
AND NOT EXISTS (SELECT 1 FROM `npc_vendor` v WHERE v.`entry` = s.`entry`
 AND (v.`slot` = s.`slot` OR v.`item` < 0 OR (v.`item` = s.`item` AND v.`type` = 1)))
AND NOT EXISTS (SELECT 1 FROM `npc_vendor` v WHERE v.`item` = -s.`entry`)
AND NOT EXISTS (SELECT 1 FROM `everlake_import_rows` r WHERE r.`tbl` = 'npc_vendor'
 AND r.`k1` = s.`entry` AND r.`k2` = s.`item` AND r.`k3` = s.`ExtendedCost` AND r.`k4` = s.`type`);
INSERT INTO `npc_vendor` (`entry`, `slot`, `item`, `maxcount`, `incrtime`, `ExtendedCost`, `type`, `PlayerConditionID`, `IgnoreFiltering`, `VerifiedBuild`) SELECT `entry`, `slot`, `item`, `maxcount`, `incrtime`, `ExtendedCost`, `type`, `PlayerConditionID`, `IgnoreFiltering`, `VerifiedBuild` FROM `everlake_import_stage` WHERE `missing` = 1;
INSERT INTO `everlake_import_rows` (`tbl`, `k1`, `k2`, `k3`, `k4`, `file`, `note`) SELECT 'npc_vendor', s.`entry`, s.`item`, s.`ExtendedCost`, s.`type`, '2026_11_10_15_world_everlake_import_slice19.sql', s.`note` FROM `everlake_import_stage` s WHERE s.`missing` = 1 ON DUPLICATE KEY UPDATE `file` = '2026_11_10_15_world_everlake_import_slice19.sql', `note` = s.`note`;
DROP TEMPORARY TABLE `everlake_import_stage`;

